-- Remove the attempt series of performances whose mark was corrected to the scorer sheet's value, so they can be re-imported from the sheet (dual-*-series2.sql). Id-independent.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DELETE pa FROM PerformanceAttempts pa JOIN Performances p ON p.Id=pa.PerformanceId JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE m.Name=N'2025 Norton-Springfield Double Dual' AND CAST(m.Date AS date)='2025-04-22' AND a.FirstName+N' '+a.LastName=N'Blake Thorne' AND e.Gender=1 AND e.Name=N'Shot Put';
DELETE pa FROM PerformanceAttempts pa JOIN Performances p ON p.Id=pa.PerformanceId JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE m.Name=N'2025 Norton-Springfield Double Dual' AND CAST(m.Date AS date)='2025-04-22' AND a.FirstName+N' '+a.LastName=N'Jack Chonko' AND e.Gender=1 AND e.Name=N'Shot Put';
DELETE pa FROM PerformanceAttempts pa JOIN Performances p ON p.Id=pa.PerformanceId JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE m.Name=N'2024 Norton-Springfield Double Dual' AND CAST(m.Date AS date)='2024-04-16' AND a.FirstName+N' '+a.LastName=N'Maclaine Bell' AND e.Gender=2 AND e.Name=N'Discus';
DELETE pa FROM PerformanceAttempts pa JOIN Performances p ON p.Id=pa.PerformanceId JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE m.Name=N'2024 Norton-Springfield Double Dual' AND CAST(m.Date AS date)='2024-04-16' AND a.FirstName+N' '+a.LastName=N'Reese Barnett' AND e.Gender=2 AND e.Name=N'Long Jump';
DELETE pa FROM PerformanceAttempts pa JOIN Performances p ON p.Id=pa.PerformanceId JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE m.Name=N'2024 Norton-Springfield Double Dual' AND CAST(m.Date AS date)='2024-04-16' AND a.FirstName+N' '+a.LastName=N'Ethan Martin' AND e.Gender=1 AND e.Name=N'Shot Put';
DELETE pa FROM PerformanceAttempts pa JOIN Performances p ON p.Id=pa.PerformanceId JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE m.Name=N'2025 New London Dual' AND CAST(m.Date AS date)='2025-05-06' AND a.FirstName+N' '+a.LastName=N'Presly McConnell' AND e.Gender=2 AND e.Name=N'Discus';
COMMIT TRANSACTION;
